import json
import math
from pathlib import Path
from pyscipopt import Model, quicksum

DATA_PATH = "/root/data.json"
REPORT_PATH = "/root/report.json"
RADIUS = 3960.0

data = json.loads(Path(DATA_PATH).read_text())

vehicle_count = int(data["vehicle_count"])
vehicle_capacity = float(data["vehicle_capacity"])
penalty_weight = float(data["penalty_weight"])
depot = {"latitude": float(data["depot"]["latitude"]), "longitude": float(data["depot"]["longitude"])}

stations_data = data["stations"]
station_ids = [int(s["id"]) for s in stations_data]
if len(station_ids) != len(set(station_ids)):
    raise ValueError("duplicate station ids")

id_to_idx = {sid: idx for idx, sid in enumerate(station_ids)}
idx_to_id = {idx: sid for sid, idx in id_to_idx.items()}

n = len(stations_data)
stations = list(range(n))
targets = {i: int(stations_data[i]["net_rebalancing_target"]) for i in stations}
initial_bikes = {i: int(stations_data[i]["initial_bikes"]) for i in stations}
station_capacity = {i: int(stations_data[i]["station_capacity"]) for i in stations}
locations = {i: {"latitude": float(stations_data[i]["latitude"]), "longitude": float(stations_data[i]["longitude"])} for i in stations}

def great_circle_miles(a, b, radius=RADIUS):
    lat1, lon1 = a["latitude"], a["longitude"]
    lat2, lon2 = b["latitude"], b["longitude"]
    deg_to_rad = math.pi / 180.0
    phi1 = (90.0 - lat1) * deg_to_rad
    phi2 = (90.0 - lat2) * deg_to_rad
    theta1 = lon1 * deg_to_rad
    theta2 = lon2 * deg_to_rad
    cos_arc = (
        math.sin(phi1) * math.sin(phi2) * math.cos(theta1 - theta2)
        + math.cos(phi1) * math.cos(phi2)
    )
    cos_arc = max(-1.0, min(1.0, cos_arc))
    return math.acos(cos_arc) * radius

START = "depot_start"
END = "depot_end"

def node_location(node):
    if node in (START, END):
        return depot
    return locations[int(node)]

from_nodes = [START] + stations
to_nodes = stations + [END]

arcs = []
for i in from_nodes:
    for j in to_nodes:
        if i == j:
            continue
        if i == START and j == END:
            continue
        arcs.append((i, j))

distance = {}
for (i, j) in arcs:
    distance[i, j] = great_circle_miles(node_location(i), node_location(j))

vehicles = list(range(vehicle_count))

model = Model("bike_rebalancing")
model.hideOutput()

# reproducibility
def set_if_available(m, name, value):
    try:
        m.setParam(name, value)
    except Exception:
        pass

for name in ["randomization/randomseedshift", "randomization/permutationseed", "randomization/lpseed"]:
    set_if_available(model, name, 0)
for name in ["randomization/permutevars", "randomization/permuteconss"]:
    set_if_available(model, name, False)

# Decision variables
x = {(v, i, j): model.addVar(vtype="B", name=f"x_{v}_{i}_{j}") for v in vehicles for (i, j) in arcs}

visit = {}
for v in vehicles:
    for i in stations:
        outgoing = quicksum(x[v, i, j] for j in to_nodes if j != i)
        visit[v, i] = outgoing

pick = {(v, i): model.addVar(vtype="I", lb=0, ub=vehicle_capacity, name=f"pick_{v}_{i}") for v in vehicles for i in stations}
drop = {(v, i): model.addVar(vtype="I", lb=0, ub=vehicle_capacity, name=f"drop_{v}_{i}") for v in vehicles for i in stations}
is_pickup = {(v, i): model.addVar(vtype="B", name=f"is_pickup_{v}_{i}") for v in vehicles for i in stations}

# load variables: at START, at stations, at END, per vehicle
load = {}
for v in vehicles:
    load[v, START] = model.addVar(vtype="C", lb=0, ub=vehicle_capacity, name=f"load_{v}_start")
    load[v, END] = model.addVar(vtype="C", lb=0, ub=vehicle_capacity, name=f"load_{v}_end")
    for i in stations:
        load[v, i] = model.addVar(vtype="C", lb=0, ub=vehicle_capacity, name=f"load_{v}_{i}")

order = {(v, i): model.addVar(vtype="C", lb=1, ub=max(1, n), name=f"order_{v}_{i}") for v in vehicles for i in stations}

dev = {i: model.addVar(vtype="C", lb=0, name=f"dev_{i}") for i in stations}

# Depot start/end degree: every vehicle must leave depot to exactly one station and return from exactly one station
for v in vehicles:
    model.addCons(quicksum(x[v, START, j] for j in stations) == 1)
    model.addCons(quicksum(x[v, i, END] for i in stations) == 1)

# Route continuity & at-most-once visit per vehicle
for v in vehicles:
    for i in stations:
        incoming = quicksum(x[v, j, i] for j in from_nodes if j != i)
        outgoing = quicksum(x[v, i, j] for j in to_nodes if j != i)
        model.addCons(incoming == outgoing)
        model.addCons(outgoing <= 1)

# Pickup/drop only allowed if visited, and mutually exclusive within a stop
for v in vehicles:
    for i in stations:
        model.addCons(pick[v, i] <= vehicle_capacity * is_pickup[v, i])
        model.addCons(drop[v, i] <= vehicle_capacity * (visit[v, i] - is_pickup[v, i] + 1 - visit[v, i]))
        # ensure is_pickup only meaningful if visited (bounds pick/drop by visit too)
        model.addCons(is_pickup[v, i] <= visit[v, i])
        model.addCons(pick[v, i] <= vehicle_capacity * visit[v, i])
        model.addCons(drop[v, i] <= vehicle_capacity * visit[v, i])

# Load propagation along selected arcs
M = 2.0 * vehicle_capacity
for v in vehicles:
    for (i, j) in arcs:
        service_at_j = (pick[v, j] - drop[v, j]) if j in stations else 0
        model.addCons(load[v, j] - load[v, i] - service_at_j <= M * (1 - x[v, i, j]))
        model.addCons(load[v, j] - load[v, i] - service_at_j >= -M * (1 - x[v, i, j]))

# MTZ subtour elimination among stations, per vehicle
for v in vehicles:
    for i in stations:
        for j in stations:
            if i != j:
                model.addCons(order[v, i] - order[v, j] + n * x[v, i, j] <= n - 1)

# Station-level aggregate constraints
total_pick = {i: quicksum(pick[v, i] for v in vehicles) for i in stations}
total_drop = {i: quicksum(drop[v, i] for v in vehicles) for i in stations}

for i in stations:
    final_inv = initial_bikes[i] - total_pick[i] + total_drop[i]
    model.addCons(final_inv >= 0)
    model.addCons(final_inv <= station_capacity[i])
    net_change = total_pick[i] - total_drop[i]
    model.addCons(net_change - targets[i] <= dev[i])
    model.addCons(targets[i] - net_change <= dev[i])

travel_distance = quicksum(distance[i, j] * x[v, i, j] for v in vehicles for (i, j) in arcs)
penalty_cost = penalty_weight * quicksum(dev[i] for i in stations)

model.setObjective(travel_distance + penalty_cost, "minimize")

model.setParam("limits/time", 300.0)
model.setParam("limits/gap", 0.0)

model.optimize()

status = str(model.getStatus()).lower()
if model.getNSols() == 0:
    raise RuntimeError(f"SCIP found no feasible solution; status={status}")

print("status:", status)
print("objective:", model.getObjVal())

# Extract solution
sol = {}
sol["status"] = status
sol["objective"] = float(model.getObjVal())

vehicle_routes = []
for v in vehicles:
    outgoing = {}
    for (i, j) in arcs:
        if model.getVal(x[v, i, j]) > 0.5:
            outgoing[i] = j
    route = [START]
    cur = START
    seen = {START}
    while cur != END:
        if cur not in outgoing:
            raise RuntimeError(f"vehicle {v} route disconnected at {cur!r}")
        nxt = outgoing[cur]
        if nxt in seen and nxt != END:
            raise RuntimeError(f"vehicle {v} cycle detected at {nxt!r}")
        route.append(nxt)
        seen.add(nxt)
        cur = nxt
    vehicle_routes.append(route)

results = {
    "vehicle_routes": vehicle_routes,
}

# Save raw solution details for report generation
raw = {
    "vehicle_routes": vehicle_routes,
    "pick": {f"{v}_{i}": model.getVal(pick[v, i]) for v in vehicles for i in stations},
    "drop": {f"{v}_{i}": model.getVal(drop[v, i]) for v in vehicles for i in stations},
    "load_start": {v: model.getVal(load[v, START]) for v in vehicles},
    "load_end": {v: model.getVal(load[v, END]) for v in vehicles},
    "load_station": {f"{v}_{i}": model.getVal(load[v, i]) for v in vehicles for i in stations},
    "objective": float(model.getObjVal()),
    "status": status,
}

Path("/root/work/raw_solution.json").write_text(json.dumps(raw, indent=2))
print("Saved raw solution.")
for v in vehicles:
    print(v, vehicle_routes[v])
